"""Documentacao da 218a leva. Uso: python docs.py"""
import os, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', 'engenharia-reversa'))
from gen_docs import fazer, leia, cadeia, prova_save, REF_JOGO, CARREIRA_PT, CARREIRA_EN

N = 218
R = [('casar_nome_com_padrao', 'zipdir_match_filename_pattern', '0x933a00', 'zipdir.cpp', 'cdecl', 'casa o nome de um item do contêiner com um padrão com `*` (`*.` vai ao último ponto), sem diferenciar maiúsculas; a vaga "{ Empty }" nunca casa', 'matches a container item name against a pattern with `*` (`*.` goes to the last dot), case-insensitively; the "{ Empty }" slot never matches'), ('id_do_conteiner', 'zget_archive_id', '0x9331c0', 'zipdir.cpp', 'cdecl', 'lê o cabeçalho do contêiner e devolve o dword +4 (0x16 .sav, 0x17 .qst; 0x14 se falhar)', 'reads the container header and returns dword +4 (0x16 .sav, 0x17 .qst; 0x14 on failure)'), ('tamanho_dos_itens_do_padrao', 'zget_matching_size', '0x933860', 'zipdir.cpp', 'cdecl', 'soma os tamanhos descomprimidos dos itens que casam com o padrão (int com sinal: acima de 2 GB dá negativo, como na original)', 'adds up the uncompressed sizes of the items matching the pattern (signed int: negative above 2 GB, as in the original)'), ('empacotar_no_conteiner', 'zadd_matching_files', '0x933610', 'zipdir.cpp', 'cdecl', 'cada arquivo da pasta que casa com o padrão (FindFirstFile) vira um item do contêiner: zopen gravando, fread/zwrite em blocos de 0x30d40, zclose', 'each folder file matching the pattern (FindFirstFile) becomes a container item: zopen for writing, fread/zwrite in 0x30d40 blocks, zclose'), ('desempacotar_do_conteiner', 'zextract_matching_files', '0x933320', 'zipdir.cpp', 'cdecl', 'cada item do contêiner cujo nome casa com o padrão vira um arquivo da pasta (zopen lendo, zread em blocos de 0x30d40, fwrite)', 'each container item whose name matches the pattern becomes a folder file (zopen for reading, zread in 0x30d40 blocks, fwrite)'), ('limpar_pasta_temporaria', 'utils_clear_temp_folder', '0x90cd50', 'utils.cpp', 'cdecl', 'monta em [0xde279c] a pasta CM3_TEMP e apaga os arquivos dela que casam com o padrão, em grupos de 100', 'builds the CM3_TEMP folder path in [0xde279c] and deletes its files matching the pattern, in groups of 100'), ('ler_do_conteiner', 'zread', '0x932c30', 'zipdir.cpp', 'cdecl', 'lê do item como o fread, cortando no fim do item; no tipo 4 decodifica o RLE (a repetição pode atravessar chamadas)', 'reads from the item like fread, clipped at the item end; on type 4 decodes the RLE (a run may span calls)'), ('gravar_no_conteiner', 'zwrite', '0x932e10', 'zipdir.cpp', 'cdecl', 'grava no item como o fwrite e soma ao tamanho no índice; no tipo 4 codifica o RLE (repetições de até 0x7f guardadas entre as chamadas)', 'writes to the item like fwrite and adds to the size in the index; on type 4 encodes the RLE (runs of up to 0x7f kept across calls)'), ('fechar_conteiner', 'zclose', '0x932b00', 'zipdir.cpp', 'cdecl', 'gravando: esvazia o buffer, fecha a repetição pendente do RLE e regrava cabeçalho e índice no começo; fecha o arquivo e libera o item', 'when writing: flushes the buffer, closes the pending RLE run and rewrites header and index at the start; closes the file and frees the item')]
ESCAPADAS = {  # nome: (explicação pt, explicação en)
    'sv_padrao_letra': ('o casamento do nome com o padrão (0x933a00) só roda na carga (o desempacotar de "*.lng" e "*.tmp"); a prova grava o .qst e a etapa de carregar depende de um save com técnico de férias, que ainda não existe', 'the name pattern match (0x933a00) only runs when loading (unpacking "*.lng" and "*.tmp"); the proof writes the .qst and the load step needs a save with a manager on holiday, which does not exist yet'),
    'sv_padrao_ponto': ('o casamento do nome com o padrão (0x933a00) só roda na carga (o desempacotar de "*.lng" e "*.tmp"); a prova grava o .qst e a etapa de carregar depende de um save com técnico de férias, que ainda não existe', 'the name pattern match (0x933a00) only runs when loading (unpacking "*.lng" and "*.tmp"); the proof writes the .qst and the load step needs a save with a manager on holiday, which does not exist yet'),
    'sv_padrao_fim': ('o casamento do nome com o padrão (0x933a00) só roda na carga (o desempacotar de "*.lng" e "*.tmp"); a prova grava o .qst e a etapa de carregar depende de um save com técnico de férias, que ainda não existe', 'the name pattern match (0x933a00) only runs when loading (unpacking "*.lng" and "*.tmp"); the proof writes the .qst and the load step needs a save with a manager on holiday, which does not exist yet'),
}
tot, ac, esc, ok = cadeia(N)
assert ok, 'cadeia sem a referencia'
assert set(esc) <= set(ESCAPADAS), ('explicar as escapadas', esc)
lac_pt = ' '.join(f'`{e}` escapou: {ESCAPADAS[e][0]}.' for e in esc) + (' (lacuna em `PENDENCIAS.md`)' if esc else '')
lac_en = ' '.join(f'`{e}` escaped: {ESCAPADAS[e][1]}.' for e in esc) + (' (gap in `PENDENCIAS.en.md`)' if esc else '')
PS = prova_save(N)  # leva do save: mutações e prova pelo .qst gravado com e sem as rotinas (cadeia.sh)
VIA_PT = 'pela prova do save' if PS else 'pela carreira até 2002-06-01, confirmando no modo comparação as que escapam'
VIA_EN = 'by the save proof' if PS else 'by the career to 2002-06-01, confirming the escaped ones in comparison mode'
PS_PT = f'Prova do save (o .qst com e sem as rotinas): {PS}. ' if PS else ''
PS_EN = f'Save proof (the .qst with and without the routines): {PS.replace("IGUAL", "EQUAL").replace("DIFERENTE", "DIFFERENT")}. ' if PS else ''
M = (f"`mutacoes/leva{N}.py` ({tot}, {VIA_PT}): {ac} acusadas. {lac_pt} {PS_PT}"
     f"Jogo real comparando até 2002-01-01: 0 divergências ({REF_JOGO}). Carreiras Rust ×2 e original até 2002-06-01: {CARREIRA_PT}")
ME = (f"`mutacoes/leva{N}.py` ({tot}, {VIA_EN}): {ac} caught. {lac_en} {PS_EN}"
      f"Real game comparing to 2002-01-01: 0 divergences ({REF_JOGO}). Rust ×2 and original careers to 2002-06-01: {CARREIRA_EN}")
fazer(N, 557, 557 + len(R), 'o contêiner do save: as consultas (o padrão do nome, o id e o tamanho dos itens); o contêiner do save: empacotar e desempacotar os arquivos da pasta e limpar a pasta temporária; o contêiner do save: ler, gravar e fechar um item (o RLE do tipo 4)', 'the saved game container: the queries (name pattern, id and item size); the saved game container: packing and unpacking the folder files and clearing the temporary folder; the saved game container: reading, writing and closing an item (the type 4 RLE)',
      [f"| `{a}()` | {e} | {c} | {f}: {d} |" for a, _, e, f, c, d, _ in R],
      [f"| `{a}()` | {e} | {c} | {f}: {d} |" for a, _, e, f, c, _, d in R],
      M, ME, [(a, g) for a, g, *_ in R], "'posicao_no_conteiner': 'position_in_container',", secao=('Simulação', 'Simulation'))
leia(N, 'o contêiner do save: as consultas (o padrão do nome, o id e o tamanho dos itens); o contêiner do save: empacotar e desempacotar os arquivos da pasta e limpar a pasta temporária; o contêiner do save: ler, gravar e fechar um item (o RLE do tipo 4)', 'the saved game container: the queries (name pattern, id and item size); the saved game container: packing and unpacking the folder files and clearing the temporary folder; the saved game container: reading, writing and closing an item (the type 4 RLE)', [(a, e, f + ', ' + c, dp, de) for a, _, e, f, c, dp, de in R], tot, ac, lac_pt, lac_en,
     campos=[('contêiner (arquivo) +0: tipo (3 sem compressão, 4 RLE; 1/2 antigos viram 3/4); valor; lê (id_do_conteiner, tamanho_dos_itens_do_padrao)', 'container (file) +0: type (3 uncompressed, 4 RLE; old 1/2 become 3/4); value; reads (id_do_conteiner, tamanho_dos_itens_do_padrao)'), ('contêiner (arquivo) +4: id do arquivo (0x16 .sav, 0x17 .qst); valor; lê (id_do_conteiner)', 'container (file) +4: archive id (0x16 .sav, 0x17 .qst); value; reads (id_do_conteiner)'), ('contêiner (arquivo) +8: quantidade de itens; valor; lê (tamanho_dos_itens_do_padrao)', 'container (file) +8: item count; value; reads (tamanho_dos_itens_do_padrao)'), ('índice do contêiner (+0xc, 0x10c por item) +4: tamanho descomprimido do item; valor; lê e soma com sinal (tamanho_dos_itens_do_padrao)', 'container index (+0xc, 0x10c per item) +4: uncompressed item size; value; reads and adds as signed (tamanho_dos_itens_do_padrao)'), ('índice do contêiner +8: nome do item (até 0x104 bytes); texto; lê (tamanho_dos_itens_do_padrao, casar_nome_com_padrao)', 'container index +8: item name (up to 0x104 bytes); text; reads (tamanho_dos_itens_do_padrao, casar_nome_com_padrao)'), ('[0xad6ad8] "{ Empty }" (vaga vazia); texto; lê (casar_nome_com_padrao)', '[0xad6ad8] "{ Empty }" (empty slot); text; reads (casar_nome_com_padrao)'), ('[0xaa2156] tabela de maiúsculas (3 bytes por caractere, via 0x90c2f0); valor; lê (casar_nome_com_padrao)', '[0xaa2156] upper-case table (3 bytes per character, via 0x90c2f0); value; reads (casar_nome_com_padrao)'), ('[0xb67a34] marca zerada depois da caixa de erro; valor; grava 0 (id_do_conteiner, tamanho_dos_itens_do_padrao, sem memória)', '[0xb67a34] flag cleared after the error box; value; writes 0 (id_do_conteiner, tamanho_dos_itens_do_padrao, out of memory)'), ('ZFILE (0xa3191 bytes, do zopen) +0x41705: buffer de leitura (0x30d40), usado como bloco do arquivo lido; bytes; grava (empacotar_no_conteiner)', 'ZFILE (0xa3191 bytes, from zopen) +0x41705: read buffer (0x30d40), used as the block read from the file; bytes; writes (empacotar_no_conteiner)'), ('ZFILE +0x72445: buffer de escrita (0x30d40), usado como bloco do item lido; bytes; grava (desempacotar_do_conteiner)', 'ZFILE +0x72445: write buffer (0x30d40), used as the block read from the item; bytes; writes (desempacotar_do_conteiner)'), ('contêiner (arquivo) +0/+8: tipo (1/2 antigos viram 3/4) e quantidade de itens; valor; lê (desempacotar_do_conteiner)', 'container (file) +0/+8: type (old 1/2 become 3/4) and item count; value; reads (desempacotar_do_conteiner)'), ('índice do contêiner (+0xc, 0x10c por item) +8: nome do item; texto; lê e copia para a lista de 1000 × 0x104 (desempacotar_do_conteiner)', 'container index (+0xc, 0x10c per item) +8: item name; text; reads and copies into the 1000 × 0x104 list (desempacotar_do_conteiner)'), ('busca de arquivos (0x4c0aa0, 0x114 bytes) +0: alça do FindFirstFile; valor; lê (empacotar_no_conteiner, limpar_pasta_temporaria)', 'file search (0x4c0aa0, 0x114 bytes) +0: FindFirstFile handle; value; reads (empacotar_no_conteiner, limpar_pasta_temporaria)'), ('busca de arquivos +0x10: nome do arquivo achado; texto; lê (empacotar_no_conteiner, limpar_pasta_temporaria)', 'file search +0x10: found file name; text; reads (empacotar_no_conteiner, limpar_pasta_temporaria)'), ('[0xde279c] pasta temporária (CM3_TEMP + barra + [0xad9c64]); texto; grava (limpar_pasta_temporaria)', '[0xde279c] temporary folder (CM3_TEMP + backslash + [0xad9c64]); text; writes (limpar_pasta_temporaria)'), ('[0xad9c64] subpasta temporária; texto; lê (limpar_pasta_temporaria)', '[0xad9c64] temporary subfolder; text; reads (limpar_pasta_temporaria)'), ('[0xad6ad8] "{ Empty }" (vaga vazia da lista); texto; lê (desempacotar_do_conteiner)', '[0xad6ad8] "{ Empty }" (empty list slot); text; reads (desempacotar_do_conteiner)'), ('[0xb67a34] marca zerada depois da caixa de erro; valor; grava 0 (empacotar_no_conteiner, desempacotar_do_conteiner)', '[0xb67a34] flag cleared after the error box; value; writes 0 (empacotar_no_conteiner, desempacotar_do_conteiner)'), ('ZFILE (0xa3191 bytes, do zopen) +0: FILE da CRT; ponteiro; lê, e grava 0 ao fechar (todas)', 'ZFILE (0xa3191 bytes, from zopen) +0: CRT FILE; pointer; reads, and writes 0 on close (all)'), ('ZFILE +4: modo (1 gravando, 0 lendo); valor; lê (todas)', 'ZFILE +4: mode (1 writing, 0 reading); value; reads (all)'), ('ZFILE +8: posição lógica no item (bytes descomprimidos); valor; lê e grava (ler_do_conteiner, gravar_no_conteiner)', 'ZFILE +8: logical position in the item (uncompressed bytes); value; reads and writes (ler_do_conteiner, gravar_no_conteiner)'), ('ZFILE +0xc: item aberto; id; lê (todas)', 'ZFILE +0xc: open item; id; reads (all)'), ('ZFILE +0x10: bytes da repetição já entregues; valor; lê e grava (ler_do_conteiner)', 'ZFILE +0x10: run bytes already delivered; value; reads and writes (ler_do_conteiner)'), ('ZFILE +0x14: contagem da repetição do RLE (1 a 0x7f); valor; lê e grava (todas)', 'ZFILE +0x14: RLE run count (1 to 0x7f); value; reads and writes (all)'), ('ZFILE +0x18: byte da repetição; valor; lê e grava (todas)', 'ZFILE +0x18: run byte; value; reads and writes (all)'), ('ZFILE +0x19: tipo do contêiner (3 sem compressão, 4 RLE); valor; lê (todas)', 'ZFILE +0x19: container type (3 uncompressed, 4 RLE); value; reads (all)'), ('ZFILE +0x19..+0x41705: cabeçalho e índice (0x416ec bytes); bytes; regrava no começo do arquivo (fechar_conteiner)', 'ZFILE +0x19..+0x41705: header and index (0x416ec bytes); bytes; rewritten at the file start (fechar_conteiner)'), ('índice do item (ZFILE +0x25 + 0x10c × item) +4: tamanho descomprimido; valor; lê (ler_do_conteiner, fechar_conteiner) e soma (gravar_no_conteiner)', 'item index entry (ZFILE +0x25 + 0x10c × item) +4: uncompressed size; value; reads (ler_do_conteiner, fechar_conteiner) and adds (gravar_no_conteiner)'), ('ZFILE +0x41705: buffer de leitura (0x30d40); bytes; grava pelo fread e lê (ler_do_conteiner)', 'ZFILE +0x41705: read buffer (0x30d40); bytes; filled by fread and read (ler_do_conteiner)'), ('ZFILE +0x72445: buffer de escrita (0x30d40); bytes; grava e esvazia pelo fwrite (gravar_no_conteiner, fechar_conteiner)', 'ZFILE +0x72445: write buffer (0x30d40); bytes; writes and flushes via fwrite (gravar_no_conteiner, fechar_conteiner)'), ('ZFILE +0xa3185 / +0xa318d: cursor do buffer de leitura e bytes lidos; valor; lê e grava (ler_do_conteiner), zera (fechar_conteiner)', 'ZFILE +0xa3185 / +0xa318d: read buffer cursor and bytes read; value; reads and writes (ler_do_conteiner), clears (fechar_conteiner)'), ('ZFILE +0xa3189: cursor do buffer de escrita; valor; lê e grava (gravar_no_conteiner, fechar_conteiner)', 'ZFILE +0xa3189: write buffer cursor; value; reads and writes (gravar_no_conteiner, fechar_conteiner)'), ('item do .sav/.qst tipo 4: RLE (byte <= 0x80 literal; > 0x80 = byte − 0x80 cópias do seguinte); formato; grava (gravar_no_conteiner, fechar_conteiner) e lê (ler_do_conteiner)', 'type 4 .sav/.qst item: RLE (byte <= 0x80 literal; > 0x80 = byte − 0x80 copies of the next); format; writes (gravar_no_conteiner, fechar_conteiner) and reads (ler_do_conteiner)')], interessa=['SGE', 'CMScout'])
